const body = $input.item.json.body || $input.item.json;
const hook = body.hook;
const brief = body.product_brief;
if (!hook || !hook.title) throw new Error('缺少选中的 Hook');
if (!brief || !brief.product_name) throw new Error('缺少产品简报');
return [{ json: { hook, product_brief: brief, language: body.language || '中文' } }];

const hook = $input.item.json.hook;
const brief = $input.item.json.product_brief;
const lang = $input.item.json.language;
const isCN = lang === '中文';
const prompt = `你是一个短视频广告编剧。根据以下信息生成一条 15 秒口播脚本，按时间轴输出。

产品：${brief.product_name}
品牌：${brief.brand || ''}
卖点：${(brief.selling_points||[]).join('、')}
受众：${brief.target_audience||''}
痛点：${brief.pain_points||''}
Hook：${hook.title}（${hook.category}）
语言：${lang}

格式：
【0-3秒】开场
【3-7秒】展示
【7-11秒】解决
【11-15秒】收束
CTA：一句话`;
return [{ json: { prompt, hook_title: hook.title, language: lang } }];

const r = $input.item.json;
const script = r.output?.[0]?.content?.[0]?.text || r.choices?.[0]?.message?.content || JSON.stringify(r);
return [{ json: { ok: true, script, hook_title: $('组装脚本生成请求体').item.json.hook_title, language: $('组装脚本生成请求体').item.json.language } }];
